class Solution {
  public int minProductSum(int[] nums1, int[] nums2) {
    // pair the largest with the smallest; values are small, so counting sort both
    int[] c1 = new int[101], c2 = new int[101];
    for (int x : nums1) c1[x]++;
    for (int x : nums2) c2[x]++;
    int sum = 0;
    for (int a = 0, b = 100; a <= 100 && b >= 0; ) {
      if (c1[a] == 0) a++;
      else if (c2[b] == 0) b--;
      else {
        int k = Math.min(c1[a], c2[b]);
        sum += k * a * b;
        c1[a] -= k;
        c2[b] -= k;
      }
    }
    return sum;
  }
}
